<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Code Beautifier Online','description'=>'Format common HTML, CSS and JavaScript code with readable indentation.','url'=>'https://smarttoolz.in/tools/code-beautifier/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">CODE BEAUTIFIER</span><h1>Code Beautifier</h1><p>Clean up indentation and spacing in HTML, CSS or JavaScript snippets.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Code<textarea id="in" rows="14" placeholder="Paste code here..."></textarea></label><label>Indent spaces<input id="n" type="number" min="1" max="8" value="2"></label><button id="go" class="tool-btn">Beautify Code</button><textarea id="out" rows="14" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy</button></div></section></main><script>(()=>{const i=document.getElementById('in'),o=document.getElementById('out'),n=document.getElementById('n');document.getElementById('go').onclick=()=>{let s=i.value.replace(/\s*([{}])\s*/g,'$1\n').replace(/\s*;\s*/g,';\n').replace(/\n\s*\n/g,'\n').trim(),lev=0,ind=' '.repeat(+n.value||2);o.value=s.split('\n').map(x=>{x=x.trim();if(x.startsWith('}'))lev=Math.max(0,lev-1);let z=ind.repeat(lev)+x;if(/[\{]$/.test(x))lev++;return z}).join('\n')};document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.value)})();</script><?php smarttoolz_tool_page_end(); ?>